keyframes.text:
@keyframes irnogM {
  0% { animation-timing-function: ease-out; transform: rotate(180deg); }
  45% { transform: rotate(198deg); }
  55% { transform: rotate(234deg); }
  100% { transform: rotate(540deg); }
}

@keyframes kzm0O3 {
  0%, 80%, 100% { opacity: 0.4; transform: scale(0.6); }
  40% { opacity: 1; transform: scale(1); }
}

@keyframes motion-slideIn {
  0.0001% { opacity: var(--comp-opacity, 1); transform: rotate(var(--comp-rotate-z, 0deg)) translate(var(--motion-translate-x, -100%), var(--motion-translate-y, 0%)); clip-path: var(--motion-clip-start, polygon(0% 0%, 100% 0%, 100% 20%, 0% 20%)); }
  100% { transform: rotate(var(--comp-rotate-z, 0deg)) translate(0px, 0px); clip-path: polygon(0% 0%, 100% 0%, 100% 100%, 0% 100%); }
}
